import pathlib,base64,hashlib,json
r=pathlib.Path('/root/rivermind-data/GAMECAM_TASK005B_GPU_MECHANISM_20261125_R1')
files={'replay_state_context02.py': '', 'replay_context02_wrapper.py': ''}
result={}
for name,encoded in files.items():
 p=r/'tools'/name
 with p.open('xb') as f:f.write(base64.b64decode(encoded))
 result[name]=hashlib.sha256(p.read_bytes()).hexdigest()
(r/'results_context02').mkdir(exist_ok=False)
print(json.dumps(result))
